SKEW_SECS = 60

# %% ../nbs/05_codex.ipynb #2008472d
def jwt_claims(token):
    "The payload of JWT `token`, decoded without verification"
    payload = token.split('.')[1]
    return json.loads(base64.urlsafe_b64decode(payload + '='*(-len(payload)%4)))

# %% ../nbs/05_codex.ipynb #fdba8e96
def mk_jwt(**claims):
    "An unsigned JWT carrying `claims`, shaped like an access token; for examples and tests"
    enc = lambda o: base64.urlsafe_b64encode(json.dumps(o).encode()).decode().rstrip('=')
    return f"{enc(dict(alg='RS256', typ='JWT'))}.{enc(claims)}.sig"

# %% ../nbs/05_codex.ipynb #6b6a339d
def token_expired(token, skew=SKEW_SECS):
    "Is JWT `token` expired, or within `skew` seconds of expiring?"
    try: exp = jwt_claims(token)['exp']
    except (ValueError, KeyError, IndexError): return True
    return time.time() >= exp - skew

# %% ../nbs/05_codex.ipynb #099399d5
def codex_tokens(auth):
    "The `tokens` block of an `auth.json` dict (or an already-unwrapped block), checked for the keys a refresh needs"
    if not isinstance(auth, dict): raise ValueError('Codex auth must be a JSON object')
    tokens = auth.get('tokens', auth)
    missing = [k for k in ('access_token', 'refresh_token') if not tokens.get(k)]
    if missing: raise ValueError(f"Codex auth is missing {', '.join(missing)}")
    return tokens

# %% ../nbs/05_codex.ipynb #46864051
def codex_info(tokens):
    "Plan type and expiry time of the access token in `tokens`"
    claims = jwt_claims(tokens['access_token'])
    return dict(plan=claims.get('https://api.openai.com/auth', {}).get('chatgpt_plan_type'), expires=claims.get('exp'))

