async def _post(path, form=False, **body):
    "POST `body` to the OpenAI auth server at `path`, as a form or as JSON, returning the JSON reply"
    async with httpx2.AsyncClient() as cli: r = await cli.post(f'{_AUTH}{path}', **(dict(data=body) if form else dict(json=body)))
    r.raise_for_status()
    return r.json()

def _merge_tokens(tokens, new): return {**tokens, **{k: new[k] for k in ('access_token', 'id_token', 'refresh_token') if k in new}}

async def _token_grant(tokens, form=False, **grant):
    "The token block after `grant` at the token endpoint, merged over `tokens`; the exchange of a sign-in code is form-encoded, a refresh JSON"
    return _merge_tokens(tokens, await _post('/oauth/token', form=form, client_id=_CLIENT_ID, **grant))

# %% ../nbs/05_codex.ipynb #48efd465
async def codex_refresh(tokens):
    "Exchange the refresh token in `tokens` for a new token block"
    return await _token_grant(tokens, grant_type='refresh_token', refresh_token=tokens['refresh_token'], scope='openid profile email')

# %% ../nbs/05_codex.ipynb #be590818
async def codex_token(tokens, force_refresh=False):
    "A valid access token from `tokens`, and the refreshed block to store when a refresh happened (else `None`)"
    if not force_refresh and not token_expired(tokens['access_token']): return tokens['access_token'], None
    tokens = await codex_refresh(tokens)
    return tokens['access_token'], tokens

