def codex_auth_path(): return Path(os.environ.get('CODEX_AUTH_PATH', '~/.codex/auth.json')).expanduser()

async def codex_auth(force_refresh=False):
    "A valid access token from the local Codex login, refreshing the file when needed"
    path = codex_auth_path()
    data = json.loads(path.read_text())
    token,new = await codex_token(codex_tokens(data), force_refresh)
    if new: path.write_text(json.dumps({**data, 'tokens':new}, indent=2))
    return token

